1	import { ChangeDetectionStrategy, Component, viewChild } from "@angular/core";
2	import { CardComponent } from "../../lib/card.component";
3	import { FancyPillComponent } from "../../lib/fancy-pill.component";
4	import { HintDirective } from "../../lib/hint.directive";
5	import { PillLegacyComponent } from "../../lib/pill-legacy.component";
6	import { PillComponent, type PillVariant } from "../../lib/pill.component";
7	
8	@Component({
9	    selector: "app-feature-116",
10	    changeDetection: ChangeDetectionStrategy.OnPush,
11	    imports: [ PillComponent, FancyPillComponent, CardComponent, PillLegacyComponent, HintDirective ],
12	    template: `
13	        <app-card heading="Feature 116" [disableTooltip]="true">
14	          <app-pill disableTooltip label='Plain'/>
15	          <app-pill  variant="success"  [disableTooltip]='!isActive'  label="Active"/>
16	          <app-pill [disableTooltip]="count > 3" [label]="title" variant="info" />
17	          <app-pill [variant]="isActive ? 'success' : 'warning'" label="Multi-line" disableTooltip></app-pill>
18	          @if (isActive) {
19	            <app-pill-legacy label="Legacy" variant="info" [disableTooltip]="true" />
20	          }
21	          <app-fancy-pill label="Fancy" icon="star" [disableTooltip]="!isActive" />
22	          <small appHint="More about feature 116" [hintDisabled]="!isActive">More</small>
23	        </app-card>
24	    `
25	})
26	export class Feature116Component {
27	    isActive = true;
28	    count = 4;
29	    title = "Title 116";
30	    statusVariant: PillVariant = "warning";
31	
32	    readonly fancy = viewChild.required(FancyPillComponent);
33	
34	    describeFancy(): string {
35	        const fancy = this.fancy();
36	        return fancy.disableTooltip() ? "quiet" : fancy.label();
37	    }
38	}
