const fs = require("fs");
const path = require("path");

const ROOT = path.join(__dirname, "src");
const TARGET_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);

function renameInTags(content) {
    let result = "";
    let i = 0;
    const n = content.length;
    while (i < n) {
        if (content.startsWith("<!--", i)) {
            let end = content.indexOf("-->", i);
            end = end === -1 ? n : end + 3;
            result += content.slice(i, end);
            i = end;
            continue;
        }
        if (content[i] === "<") {
            let j = i + 1;
            if (content[j] === "/") j++;
            const nameStart = j;
            while (j < n && /[a-zA-Z0-9-]/.test(content[j])) j++;
            const tagName = content.slice(nameStart, j);
            let tagEnd = j;
            let quote = null;
            while (tagEnd < n) {
                const ch = content[tagEnd];
                if (quote) {
                    if (ch === quote) quote = null;
                } else {
                    if (ch === '"' || ch === "'") quote = ch;
                    else if (ch === ">") { tagEnd++; break; }
                }
                tagEnd++;
            }
            let tagText = content.slice(i, tagEnd);
            if (TARGET_TAGS.has(tagName)) {
                tagText = tagText.replace(/\bdisableTooltip\b/g, "hideHint");
            }
            result += tagText;
            i = tagEnd;
        } else {
            result += content[i];
            i++;
        }
    }
    return result;
}

function renameChains(content) {
    return content.replace(
        /\b(fancyRef|fancy|firstPill|pill)(\(\))?(\?)?\.disableTooltip\(\)/g,
        (m, name, parens, q) => `${name}${parens || ""}${q || ""}.hideHint()`
    );
}

function walk(dir, cb) {
    for (const entry of fs.readdirSync(dir, { withFileTypes: true })) {
        const full = path.join(dir, entry.name);
        if (entry.isDirectory()) walk(full, cb);
        else cb(full);
    }
}

// 1. lib files that fully belong to the renamed input
const fullRenameFiles = [
    "app/lib/pill.component.ts",
    "app/lib/fancy-pill.component.ts",
    "app/lib/status-pill.component.ts",
].map(p => path.join(ROOT, p));

for (const f of fullRenameFiles) {
    let content = fs.readFileSync(f, "utf8");
    content = content.replace(/\bdisableTooltip\b/g, "hideHint");
    fs.writeFileSync(f, content);
    console.log("full-rename", f);
}

// 2. pill-tray.component.ts: only the pill + fancyPill setInput calls
{
    const f = path.join(ROOT, "app/lib/pill-tray.component.ts");
    let content = fs.readFileSync(f, "utf8");
    content = content.replace(
        /(const pill = this\.slot\(\)\.createComponent\(PillComponent\);[\s\S]*?)setInput\("disableTooltip"/,
        (m, pre) => pre + 'setInput("hideHint"'
    );
    content = content.replace(
        /(const pill = this\.slot\(\)\.createComponent\(FancyPillComponent\);[\s\S]*?)setInput\("disableTooltip"/,
        (m, pre) => pre + 'setInput("hideHint"'
    );
    fs.writeFileSync(f, content);
    console.log("pill-tray updated");
}

// 3. styles.css
{
    const f = path.join(__dirname, "src", "styles.css");
    let content = fs.readFileSync(f, "utf8");
    content = content
        .replace(/app-pill\[disableTooltip\]/g, "app-pill[hideHint]")
        .replace(/app-fancy-pill\[disableTooltip\]/g, "app-fancy-pill[hideHint]")
        .replace(/app-status-pill\[disableTooltip\]/g, "app-status-pill[hideHint]");
    fs.writeFileSync(f, content);
    console.log("styles.css updated");
}

// 4. features: tag-based template rename + chain rename, for .ts and .html
const featuresDir = path.join(ROOT, "app", "features");
let changed = 0;
walk(featuresDir, file => {
    if (!file.endsWith(".ts") && !file.endsWith(".html")) return;
    let content = fs.readFileSync(file, "utf8");
    const original = content;
    content = renameInTags(content);
    content = renameChains(content);
    if (content !== original) {
        fs.writeFileSync(file, content);
        changed++;
    }
});
console.log("feature files changed:", changed);

